/* global Office, Excel, Word, console, FileReader, Image, URL, Blob, atob, Uint8Array, document, localStorage, fetch */

const DEFAULT_MODEL = "gpt-4o-mini";
const DEFAULT_API_URL = "https://api.openai.com/v1/chat/completions";
const DEFAULT_IMAGE_MODEL = "gpt-image-1";
const MAX_RETRY = 3;

let HOST_APP = "";

// Proxy CORS khi chèn ảnh từ URL.
const CORS_PROXIES = [
  (url) => "https://corsproxy.io/?url=" + encodeURIComponent(url),
  (url) => "https://api.allorigins.win/raw?url=" + encodeURIComponent(url),
  (url) => "https://api.codetabs.com/v1/proxy/?quest=" + encodeURIComponent(url),
  (url) => "https://thingproxy.freeboard.io/fetch/" + url,
  (url) => url,
];

Office.onReady((info) => {
  if (info.host === Office.HostType.Excel) {
    HOST_APP = "Excel";
  } else if (info.host === Office.HostType.Word) {
    HOST_APP = "Word";

    const p = document.getElementById("prompt_input");
    if (p) {
      p.placeholder =
        "VD: Viết đoạn văn giới thiệu công ty\n" +
        "VD: Sửa đoạn đang chọn cho chuyên nghiệp hơn\n" +
        "VD: Dịch đoạn đang chọn sang tiếng Anh\n" +
        "VD: Đổi đoạn đang chọn thành giọng văn trang trọng";
    }
  }

  const runButton = document.getElementById("run_button");
  const clearButton = document.getElementById("clear_button");

  if (runButton) runButton.onclick = executeCommand;
  if (clearButton) clearButton.onclick = clearAll;

  const savedKey = localStorage.getItem("openai_api_key");
  if (savedKey) {
    document.getElementById("api_key_input").value = savedKey;
  }

  const savedApiUrl = localStorage.getItem("openai_api_url") || DEFAULT_API_URL;
  document.getElementById("api_url_input").value = savedApiUrl;

  const modelSelect = document.getElementById("model_select");
  if (modelSelect) {
    const savedModel = localStorage.getItem("openai_model");
    if (savedModel) modelSelect.value = savedModel;
  }
});

function getModel() {
  const modelSelect = document.getElementById("model_select");
  return modelSelect ? modelSelect.value : DEFAULT_MODEL;
}

function getApiUrl() {
  const input = document.getElementById("api_url_input");
  const value = input ? input.value.trim() : "";
  return value || DEFAULT_API_URL;
}

function getImageApiUrl() {
  const chatUrl = getApiUrl();

  if (chatUrl.includes("/chat/completions")) {
    return chatUrl.replace(/\/chat\/completions.*$/i, "/images/generations");
  }

  return "https://api.openai.com/v1/images/generations";
}

function setStatus(msg, type) {
  const el = document.getElementById("status_area");
  el.className = "status " + type;
  el.innerText = msg;
}

// ==================== GỌI OPENAI / API TƯƠNG THÍCH OPENAI ====================
async function callOpenAI(apiKey, prompt, options = {}) {
  const model = options.model || getModel();
  const apiUrl = getApiUrl();

  const systemMessage =
    options.system ||
    "Bạn là trợ lý AI tiếng Việt giỏi Excel, Word và Office.js. Trả lời chính xác, ngắn gọn, hữu ích.";

  const payload = {
    model,
    messages: [
      {
        role: "system",
        content: systemMessage,
      },
      {
        role: "user",
        content: prompt,
      },
    ],
    temperature: options.temperature ?? 0.2,
    max_tokens: options.maxTokens || 8192,
  };

  let response;

  try {
    response = await fetch(apiUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer " + apiKey,
      },
      body: JSON.stringify(payload),
    });
  } catch (e) {
    throw new Error(
      "Không gọi được API. Có thể do mất mạng, sai API URL, hoặc bị CORS khi gọi trực tiếp từ add-in.\n" +
        "Chi tiết: " +
        e.message
    );
  }

  const data = await response.json().catch(() => ({}));

  if (!response.ok) {
    const msg =
      data.error?.message ||
      data.message ||
      "Lỗi API HTTP " + response.status;
    throw new Error(msg);
  }

  const text = data.choices?.[0]?.message?.content;

  if (!text) {
    throw new Error("API không trả về nội dung hợp lệ.");
  }

  return text.trim();
}

function cleanCode(code) {
  if (!code) return "";

  code = code
    .replace(/```javascript/gi, "")
    .replace(/```js/gi, "")
    .replace(/```/g, "")
    .trim();

  code = code.replace(
    /^[\s\S]*?await\s+(Excel|Word)\.run\s*\(\s*async\s*\([^)]*\)\s*=>\s*\{/i,
    ""
  );

  code = code.replace(
    /await\s+context\.sync\(\)\s*;?\s*\}\s*\)\s*;?\s*$/i,
    ""
  );

  return code.trim();
}

function colToLetter(n) {
  let s = "";
  n = n + 1;

  while (n > 0) {
    const m = (n - 1) % 26;
    s = String.fromCharCode(65 + m) + s;
    n = Math.floor((n - 1) / 26);
  }

  return s;
}

// ==================== ẢNH URL -> BASE64 ====================
function blobToPngBase64(blob) {
  return new Promise((resolve, reject) => {
    const objUrl = URL.createObjectURL(blob);
    const img = new Image();
    img.crossOrigin = "anonymous";

    img.onload = () => {
      try {
        const canvas = document.createElement("canvas");
        canvas.width = img.naturalWidth;
        canvas.height = img.naturalHeight;

        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0);

        const dataUrl = canvas.toDataURL("image/png");
        URL.revokeObjectURL(objUrl);

        resolve(dataUrl.split(",")[1]);
      } catch (e) {
        URL.revokeObjectURL(objUrl);
        reject(e);
      }
    };

    img.onerror = () => {
      URL.revokeObjectURL(objUrl);
      reject(new Error("Không đọc được ảnh."));
    };

    img.src = objUrl;
  });
}

async function insertBase64ToCell(base64, targetCell, fitCell) {
  const clean = base64.replace(/\s/g, "");

  await Excel.run(async (context) => {
    const sheet = context.workbook.worksheets.getActiveWorksheet();
    const image = sheet.shapes.addImage(clean);

    image.load("width, height");
    await context.sync();

    const cell = sheet.getRange(targetCell);
    cell.load("left, top, width, height");
    await context.sync();

    image.left = cell.left;
    image.top = cell.top;

    if (fitCell) {
      image.width = cell.width;
      image.height = cell.height;
    } else if (image.width > 350) {
      const ratio = 350 / image.width;
      image.width = 350;
      image.height = image.height * ratio;
    }

    await context.sync();
  });
}

async function urlToBase64(url) {
  let lastErr = "";

  for (let i = 0; i < CORS_PROXIES.length; i++) {
    const proxyUrl = CORS_PROXIES[i](url);

    try {
      setStatus(
        `🖼️ Đang tải ảnh, nguồn ${i + 1}/${CORS_PROXIES.length}...`,
        "loading"
      );

      const response = await fetch(proxyUrl, { method: "GET" });

      if (!response.ok) {
        lastErr = "HTTP " + response.status;
        continue;
      }

      const blob = await response.blob();

      if (blob.size < 100) {
        lastErr = "Ảnh rỗng hoặc không hợp lệ.";
        continue;
      }

      const pngBase64 = await blobToPngBase64(blob);

      if (pngBase64 && pngBase64.length > 100) {
        return pngBase64;
      }

      lastErr = "Convert PNG thất bại.";
    } catch (e) {
      lastErr = e.message;
      console.warn(`Proxy ${i + 1} lỗi:`, lastErr);
    }
  }

  throw new Error(
    "Đã thử nhiều nguồn nhưng không tải/chèn được ảnh. Lỗi cuối: " + lastErr
  );
}

async function insertImageFromUrl(imageUrl, targetCell, fitCell) {
  const base64 = await urlToBase64(imageUrl);

  setStatus("📥 Đang chèn ảnh vào Excel...", "loading");

  await insertBase64ToCell(base64, targetCell, fitCell);

  setStatus(`✅ Đã chèn ảnh vào ô ${targetCell}!`, "success");
}

// ==================== VẼ ẢNH BẰNG OPENAI ====================
async function generateAndInsertImage(apiKey, description, targetCell) {
  const imageApiUrl = getImageApiUrl();

  setStatus("🎨 AI đang tạo ảnh...", "loading");

  let response;

  try {
    response = await fetch(imageApiUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer " + apiKey,
      },
      body: JSON.stringify({
        model: DEFAULT_IMAGE_MODEL,
        prompt: description,
        size: "1024x1024",
      }),
    });
  } catch (e) {
    throw new Error(
      "Không gọi được API tạo ảnh. Có thể do CORS, mạng, hoặc API URL không hỗ trợ tạo ảnh.\n" +
        "Chi tiết: " +
        e.message
    );
  }

  const data = await response.json().catch(() => ({}));

  if (!response.ok) {
    throw new Error(data.error?.message || "Lỗi API tạo ảnh HTTP " + response.status);
  }

  const item = data.data?.[0];

  if (!item) {
    throw new Error("API không trả về ảnh.");
  }

  let base64 = item.b64_json || null;

  if (!base64 && item.url) {
    base64 = await urlToBase64(item.url);
  }

  if (!base64) {
    throw new Error("Không lấy được dữ liệu ảnh từ API.");
  }

  setStatus("📥 Đang chèn ảnh vào Excel...", "loading");

  await insertBase64ToCell(base64, targetCell, false);

  setStatus(`✅ Đã tạo và chèn ảnh vào ô ${targetCell}!`, "success");
}

// ==================== PHÂN LOẠI CHAT / ACTION ====================
async function classifyIntent(apiKey, userPrompt) {
  const prompt = `Phân loại yêu cầu sau. Chỉ trả về đúng 1 từ: CHAT hoặc ACTION.

ACTION = yêu cầu cần thao tác/thay đổi dữ liệu, công thức, định dạng trong Excel/Word.
Ví dụ ACTION:
- tính tổng cột A
- tô đỏ ô lớn hơn 100
- lọc trùng
- sắp xếp vùng chọn
- đổi font vùng bôi đen
- viết đoạn văn vào Word
- sửa đoạn đang chọn

CHAT = hỏi đáp, giải thích, tư vấn, không cần sửa file.
Ví dụ CHAT:
- giải thích hàm VLOOKUP
- thủ đô nước Pháp là gì
- tư vấn cách trồng cây
- bạn là ai

Yêu cầu:
${userPrompt}

Trả về CHAT hoặc ACTION:`;

  const result = await callOpenAI(apiKey, prompt, {
    temperature: 0,
    maxTokens: 20,
    system: "Bạn là bộ phân loại ý định. Chỉ trả về CHAT hoặc ACTION.",
  });

  return result.toUpperCase().includes("ACTION") ? "ACTION" : "CHAT";
}

// ==================== CHAT ====================
async function handleChat(apiKey, userPrompt) {
  const cellMatch = userPrompt.match(
    /\b(?:vào|ghi vào|điền vào|trả lời vào|ô)\s*([A-Z]{1,3}\d{1,7})\b/i
  );

  const targetCell = cellMatch ? cellMatch[1].toUpperCase() : null;

  const chatPrompt = `Bạn là trợ lý AI thông minh, thân thiện.
Trả lời bằng tiếng Việt rõ ràng, hữu ích.
${targetCell ? "Lưu ý: trả lời ngắn gọn vì sẽ ghi vào một ô Excel." : ""}

Câu hỏi/yêu cầu:
${userPrompt}

Trả lời:`;

  const answer = await callOpenAI(apiKey, chatPrompt, {
    temperature: 0.3,
  });

  if (targetCell && HOST_APP === "Excel") {
    await Excel.run(async (context) => {
      const sheet = context.workbook.worksheets.getActiveWorksheet();
      sheet.getRange(targetCell).values = [[answer]];
      await context.sync();
    });

    setStatus(`✅ Đã trả lời và ghi vào ô ${targetCell}:\n\n${answer}`, "success");
  } else {
    setStatus(`💬 ${answer}`, "success");
  }
}

// ==================== BỐI CẢNH EXCEL ====================
async function getExcelContext() {
  let info = "";

  await Excel.run(async (ctx) => {
    const sel = ctx.workbook.getSelectedRange();
    sel.load("address, rowCount, columnCount, values, columnIndex, rowIndex");

    const sheet = ctx.workbook.worksheets.getActiveWorksheet();
    sheet.load("name");

    await ctx.sync();

    const isMulti = sel.rowCount > 1 || sel.columnCount > 1;
    const selAddr = sel.address.split("!").pop();

    info += `- Sheet: "${sheet.name}"\n`;

    if (isMulti) {
      info += `\n### NGƯỜI DÙNG ĐANG BÔI ĐEN VÙNG: ${selAddr}\n`;
      info += `### Dữ liệu vùng bôi đen đã được đọc sẵn vào biến selData.\n`;
      info += `- Kích thước vùng: ${sel.rowCount} dòng x ${sel.columnCount} cột\n`;
      info += `- Ánh xạ cột:\n`;

      for (let j = 0; j < sel.columnCount; j++) {
        info += `    selData[i][${j}] = cột ${colToLetter(sel.columnIndex + j)}\n`;
      }

      const preview = sel.values
        .slice(0, 25)
        .map((r, i) => `  selData[${i}] = [${r.join(" | ")}]`)
        .join("\n");

      info += `- Nội dung xem trước:\n${preview}\n`;

      if (sel.rowCount > 25) {
        info += `  ...(tổng ${sel.rowCount} dòng)\n`;
      }
    } else {
      info += `- Đang chọn 1 ô: ${selAddr}\n`;

      const used = sheet.getUsedRangeOrNullObject();
      used.load("address, values, rowCount, columnCount");

      await ctx.sync();

      if (!used.isNullObject) {
        info += `- Vùng có dữ liệu: ${used.address} (${used.rowCount} dòng x ${used.columnCount} cột)\n`;

        const preview = used.values
          .slice(0, 20)
          .map((r, i) => `  dòng ${i}: [${r.join(" | ")}]`)
          .join("\n");

        info += `- Dữ liệu xem trước:\n${preview}\n`;
      }
    }
  });

  return info;
}

async function runExcelCode(code) {
  await Excel.run(async (context) => {
    const sheet = context.workbook.worksheets.getActiveWorksheet();
    const workbook = context.workbook;

    const sel = workbook.getSelectedRange();
    sel.load("values, rowCount, columnCount, address, columnIndex, rowIndex");

    await context.sync();

    const selData = sel.values;
    const selInfo = {
      address: sel.address,
      rowCount: sel.rowCount,
      colCount: sel.columnCount,
      startCol: sel.columnIndex,
      startRow: sel.rowIndex,
    };

    const runner = new Function(
      "context",
      "sheet",
      "workbook",
      "Excel",
      "selData",
      "selInfo",
      `return (async () => { ${code}\nawait context.sync(); })();`
    );

    await runner(context, sheet, workbook, Excel, selData, selInfo);

    await context.sync();
  });
}

// ==================== BỐI CẢNH WORD ====================
async function getWordContext() {
  let info = "";

  await Word.run(async (ctx) => {
    const sel = ctx.document.getSelection();
    sel.load("text");

    await ctx.sync();

    info += `- Văn bản đang chọn: "${sel.text || "(chưa chọn gì)"}"\n`;
  });

  return info;
}

async function runWordCode(code) {
  await Word.run(async (context) => {
    const doc = context.document;
    const selection = context.document.getSelection();
    const body = context.document.body;

    const runner = new Function(
      "context",
      "doc",
      "selection",
      "body",
      "Word",
      `return (async () => { ${code}\nawait context.sync(); })();`
    );

    await runner(context, doc, selection, body, Word);

    await context.sync();
  });
}

