// ==================== HÀM CHÍNH ====================
async function executeCommand() {
  const apiKey = document.getElementById("api_key_input").value.trim();
  const apiUrl = document.getElementById("api_url_input").value.trim() || DEFAULT_API_URL;
  const userPrompt = document.getElementById("prompt_input").value.trim();
  const btn = document.getElementById("run_button");

  if (!apiKey) {
    setStatus("⚠️ Bạn chưa nhập API key.", "error");
    return;
  }

  if (!userPrompt) {
    setStatus("⚠️ Bạn chưa nhập yêu cầu.", "error");
    return;
  }

  localStorage.setItem("openai_api_key", apiKey);
  localStorage.setItem("openai_api_url", apiUrl);

  const modelSelect = document.getElementById("model_select");
  if (modelSelect) {
    localStorage.setItem("openai_model", modelSelect.value);
  }

  btn.disabled = true;

  try {
    // Ưu tiên xử lý ảnh trong Excel.
    if (HOST_APP === "Excel") {
      const urlMatch = userPrompt.match(/https?:\/\/[^\s"']+/i);
      const isImageCmd = /ảnh|hình|image|picture/i.test(userPrompt);

      if (isImageCmd) {
        const cellMatch = userPrompt.match(
          /\b(?:vào|tại|ô)\s*([A-Z]{1,3}\d{1,7})\b/i
        );

        const targetCell = cellMatch ? cellMatch[1].toUpperCase() : "A1";

        if (urlMatch) {
          const fitCell = /vừa ô|khít ô|vừa khít|fit/i.test(userPrompt);
          await insertImageFromUrl(urlMatch[0], targetCell, fitCell);
          return;
        }

        let desc = userPrompt
          .replace(/chèn|thêm|vẽ|tạo|sinh|generate|bằng ai/gi, "")
          .replace(/\bảnh\b|\bhình\b|image|picture/gi, "")
          .replace(/\b(?:vào|tại|ô)\s*[A-Z]{1,3}\d{1,7}\b/gi, "")
          .trim();

        if (!desc) desc = userPrompt;

        await generateAndInsertImage(apiKey, desc, targetCell);
        return;
      }
    }

    // Phân loại chat/action.
    setStatus("🧠 Đang hiểu yêu cầu...", "loading");

    const intent = await classifyIntent(apiKey, userPrompt);
    console.log("Intent:", intent);

    if (intent === "CHAT") {
      setStatus("💬 Đang trả lời...", "loading");
      await handleChat(apiKey, userPrompt);
      return;
    }

    // ACTION.
    let contextInfo;
    let rules;
    let runFunc;

    if (HOST_APP === "Excel") {
      contextInfo = await getExcelContext();
      rules = EXCEL_RULES;
      runFunc = runExcelCode;
    } else if (HOST_APP === "Word") {
      contextInfo = await getWordContext();
      rules = WORD_RULES;
      runFunc = runWordCode;
    } else {
      throw new Error("Add-in chỉ hỗ trợ Excel hoặc Word.");
    }

    let lastError = "";
    let code = "";

    for (let attempt = 1; attempt <= MAX_RETRY; attempt++) {
      setStatus(
        attempt === 1
          ? "⚙️ Đang viết code xử lý..."
          : `🔄 Đang thử lại ${attempt}/${MAX_RETRY}...`,
        "loading"
      );

      const prompt =
        attempt === 1
          ? `${rules}

## BỐI CẢNH:
${contextInfo}

## YÊU CẦU:
${userPrompt}

Hãy viết code đúng theo yêu cầu. Chỉ trả về code JS thuần:`
          : `${rules}

## BỐI CẢNH:
${contextInfo}

## YÊU CẦU:
${userPrompt}

## CODE BỊ LỖI:
${code}

## LỖI:
${lastError}

Hãy viết lại code đúng. Chỉ trả về code JS thuần:`;

      code = cleanCode(
        await callOpenAI(apiKey, prompt, {
          temperature: 0.1,
          maxTokens: 8192,
          system:
            "Bạn là chuyên gia Office.js. Chỉ trả về code JavaScript thuần, không markdown, không giải thích.",
        })
      );

      console.log(`=== Attempt ${attempt} - Code (${HOST_APP}) ===\n${code}\n===`);

      try {
        await runFunc(code);

        setStatus(
          attempt === 1
            ? "✅ Thành công!"
            : `✅ Thành công sau ${attempt} lần thử!`,
          "success"
        );

        return;
      } catch (e) {
        lastError = e.message;
        console.warn(`Attempt ${attempt} lỗi:`, lastError);

        if (attempt === MAX_RETRY) {
          throw new Error(`Thử ${MAX_RETRY} lần vẫn lỗi: ${lastError}`);
        }
      }
    }
  } catch (error) {
    console.error(error);
    setStatus("❌ " + error.message, "error");
  } finally {
    btn.disabled = false;
  }
}

function clearAll() {
  document.getElementById("prompt_input").value = "";
  document.getElementById("status_area").className = "status";
  document.getElementById("status_area").innerText = "";
}